  "root_cause": {
    "category": "process_crash",
    "service": "docker-daemon",
    "summary": "Docker daemon process crashed or stopped, removing its Unix socket and causing queue-master to fail to launch workers."
  },
  "confidence": "medium",
  "causal_chain": [
    {
      "claim": "The Unix socket /var/run/docker.sock is missing (No such file or directory).",
      "status": "confirmed",
      "cites": ["queue-master-L0000c"]
    },
    {
      "claim": "Queue-master's outbound calls to the Docker daemon fail with AFUNIXSocketException due to the missing socket.",
      "status": "confirmed",
      "cites": ["queue-master-L00003", "queue-master-L0000c"]
    },
    {
      "claim": "Because queue-master cannot talk to Docker daemon, its DockerSpawner fails to launch or remove worker containers.",
      "status": "confirmed",
      "cites": ["queue-master-L0000c"]
    },
    {
      "claim": "The failure to launch workers leads to a backlog of pending jobs, causing increased latency or errors in user‑visible services (gateway, orders, inventory, payments).",
      "status": "uncertain",
      "cites": ["queue-master-L00003"]
    }
  ],
  "alternatives": [
    {
      "category": "config_regression",
      "service": "queue-master",
      "why_less_likely": "The errors indicate a missing socket file rather than a mere connection refusal or timeout, and the persistent failures suggest the Docker daemon is not running rather than a one‑time misconfiguration.",
      "cites": ["queue-master-L0000c", "queue-master-L00003"]
    },
    {
      "category": "edge_unreachable",
      "service": "queue-master",
      "why_less_likely": "The observed AFUNIXSocketException reports \"No such file or directory\" for the Unix socket, which is a filesystem issue, not a network timeout or name‑resolution failure; no other services show network‑related errors.",
      "cites": ["queue-master-L0000c"]
    }
  ]
}
